public async IAsyncEnumerable<Message> ReceiveAllAsync(
    string queueUrl,
    [EnumeratorCancellation] CancellationToken cancellationToken)
{
    while (!cancellationToken.IsCancellationRequested)
    {
        var response = await _sqs.ReceiveMessageAsync(queueUrl, cancellationToken);
        if (response.Messages.Count == 0)
        {
            yield break;
        }

        foreach (var message in response.Messages)
        {
            yield return message;
        }
    }
}

public async Task DrainAsync(string queueUrl, CancellationToken cancellationToken)
{
    await foreach (var message in ReceiveAllAsync(queueUrl).WithCancellation(cancellationToken))
    {
        await HandleAsync(message, cancellationToken);
    }
}
